mapper.select:
SELECT (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = X.CLAIM_TYPE) AS CLAIM_TEXT, X.DATE_1, X.DATE_2, X.DATE_3, X.DATE_4, X.DATE_5, X.DATE_6, X.DATE_7, (X.DATE_1+X.DATE_2+X.DATE_3+X.DATE_4+X.DATE_5+X.DATE_6+X.DATE_7) AS T_DATE, X.CLAIM_TYPE FROM ( SELECT A.CLAIM_TYPE, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),0,1)),0) AS DATE_1, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),1,1)),0) AS DATE_2, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),2,1)),0) AS DATE_3, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),3,1)),0) AS DATE_4, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),4,1)),0) AS DATE_5, NVL(SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0),5,1)),0) AS DATE_6, SUM(DECODE(ROUND(A.DF_DATE-A.CD_DATE,0)-6-ABS(ROUND(A.DF_DATE-A.CD_DATE,0)-6),0,1,0)) AS DATE_7 FROM KEPAVCDT A , (SELECT CODE FROM ICOMCOD1 WHERE TYPE = 'VC01' AND TEXT3 = 'C') B WHERE TO_CHAR(A.CD_DATE,'YYYYMMDD') BETWEEN #{st_fromDate} AND #{st_toDate} AND A.CLAIM_TYPE = B.CODE
AND A.CLAIM_GRADE = #{st_claim_flag}
AND A.CLAIM_TYPE = #{st_claim_text}
GROUP BY A.CLAIM_TYPE ) X ORDER BY X.CLAIM_TYPE
